import { FormEvent, useState } from 'react';
import { JxInputField, JxSelect, JxSwitch, JxButton, JxAlert } from '@jinx-ui/react';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const roleOptions = [
  { value: 'member', label: 'Участник' },
  { value: 'admin', label: 'Администратор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

export default function InviteTeamForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [submitted, setSubmitted] = useState(false);

  const isEmailValid = EMAIL_PATTERN.test(email);
  const showError = email.length > 0 && !isEmailValid;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isEmailValid) return;
    setSubmitted(true);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)', maxWidth: 420 }}>
      {submitted && (
        <JxAlert
          intent="success"
          title="Приглашение отправлено"
          onClick={undefined}
        >
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 'var(--jx-r-sm)' }}>
            <span>Приглашение для {email} успешно отправлено.</span>
            <JxButton
              variant="ghost"
              size="sm"
              iconOnly
              aria-label="Закрыть сообщение"
              onClick={() => setSubmitted(false)}
            >
              ×
            </JxButton>
          </div>
        </JxAlert>
      )}

      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          helperText="Мы отправим приглашение на этот адрес"
          errorText={showError ? 'Введите корректный адрес почты' : undefined}
        />

        <JxSelect
          label="Роль"
          options={roleOptions}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!isEmailValid}>
          Отправить приглашение
        </JxButton>
      </form>
    </div>
  );
}

